#include <stdio.h>

static void show_level(int index)
{
    const int levels[] = {8, 4, 9};
    int length = (int)(sizeof levels / sizeof levels[0]);
    if (index < 0 || index >= length) {
        puts("invalid");
        return;
    }
    printf("%d\n", levels[index]);
}

int main(void)
{
    show_level(2);
    show_level(-1);
    show_level(3);
    return 0;
}

